var n=`0559-gers-ogaily`;var t=`world-0559`;var a=`KW`;var o=`western-asia`;var r=8;var s=51;var g={en:`Gers Ogaily`,ua:`Кекс герс оґайлі`};var d={en:`A traditional dish from Kuwait, centered on chicken egg, all-purpose flour, whole cow milk, baking powder. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Кувейт. Основні складники: куряче яйце, пшеничне борошно універсальне, цільне коров'яче молоко, розпушувач тіста. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:7,i:[[`chicken-egg`,3,`pcs`],[`white-granulated-sugar`,170,`g`],[`unsalted-butter`,90,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`all-purpose-flour`,220,`g`],[`whole-cow-milk`,160,`ml`],[`baking-powder`,9,`g`],[`ground-cardamom`,5,`g`],[`saffron-threads`,.3,`g`]]},{en:`Bake in a preheated 180°C oven for about 35 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 35 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:35,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`white-sesame-seeds`,35,`g`]]}];var u={slug:n,id:t,country:`KW`,region:o,servings:8,minutes:51,title:g,text:d,steps:l};export{a as country,u as default,t as id,s as minutes,o as region,r as servings,n as slug,l as steps,d as text,g as title};